cypress_script:
describe('Keyboard Input Feedback', () => {
  it('should display the pressed key', () => {
    cy.visit('https://the-internet.herokuapp.com/key_presses');
    cy.get('#target').type('A');
    cy.get('#result').should('be.visible');
  });

  it('should not change URL on key press', () => {
    cy.visit('https://the-internet.herokuapp.com/key_presses');
    cy.get('#target').type('A');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/key_presses');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Keyboard Input Feedback', () => {
  test('should display the pressed key', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/key_presses');
    await page.fill('#target', 'A');
    const result = await page.locator('#result').isVisible();
    expect(result).toBe(true);
  });

  test('should not change URL on key press', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/key_presses');
    await page.fill('#target', 'A');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/key_presses');
  });
});
